import{_ as s,o as a,c as n,ag as t}from"./chunks/framework.gmyryY1Z.js";const u=JSON.parse('{"title":"Monorepo New Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/evolution/monorepo.md","filePath":"en/evolution/monorepo.md","lastUpdated":null}'),i={name:"en/evolution/monorepo.md"};function o(c,e,p,r,l,d){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="monorepo-new-architecture" tabindex="-1">Monorepo New Architecture <a class="header-anchor" href="#monorepo-new-architecture" aria-label="Permalink to &quot;Monorepo New Architecture&quot;">​</a></h1><blockquote><p>This chapter describes the current architecture on the <code>main</code> branch — the long-term direction for Fast Vue3.</p></blockquote><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><ol><li><strong>Low long-term maintenance cost</strong> — Clear package boundaries, avoid over-abstraction</li><li><strong>Scalability</strong> — Adding a new UI ecosystem = one new app</li><li><strong>Shared-first</strong> — Infrastructure written once, reused everywhere</li><li><strong>Unified toolchain</strong> — All apps share the same lint, tsconfig, vite-config</li></ol><h2 id="complete-directory-structure" tabindex="-1">Complete Directory Structure <a class="header-anchor" href="#complete-directory-structure" aria-label="Permalink to &quot;Complete Directory Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fast-vue3/</span></span>
<span class="line"><span>├── apps/                             # UI ecosystem app layer</span></span>
<span class="line"><span>│   ├── web-antd/                     # Ant Design Vue (port 3001)</span></span>
<span class="line"><span>│   ├── web-ele/                      # Element Plus (port 3002)</span></span>
<span class="line"><span>│   ├── web-naive/                    # Naive UI (port 3003)</span></span>
<span class="line"><span>│   ├── web-arco/                     # Arco Design (port 3004)</span></span>
<span class="line"><span>│   └── web-tdesign/                  # TDesign Vue Next (port 3005)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── packages/                         # Shared business packages</span></span>
<span class="line"><span>│   ├── @core/</span></span>
<span class="line"><span>│   │   └── shared/                   # Core types + constants</span></span>
<span class="line"><span>│   ├── utils/                        # Utility functions</span></span>
<span class="line"><span>│   ├── stores/                       # Pinia stores</span></span>
<span class="line"><span>│   ├── locales/                      # i18n resources</span></span>
<span class="line"><span>│   └── effects/</span></span>
<span class="line"><span>│       ├── request/                  # HTTP client</span></span>
<span class="line"><span>│       └── access/                   # Route access guard</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── internal/                         # Engineering infrastructure</span></span>
<span class="line"><span>│   ├── vite-config/                  # Vite config factory (requires pre-build)</span></span>
<span class="line"><span>│   ├── tsconfig/                     # Base TypeScript configs</span></span>
<span class="line"><span>│   └── lint-configs/</span></span>
<span class="line"><span>│       ├── eslint-config/</span></span>
<span class="line"><span>│       ├── prettier-config/</span></span>
<span class="line"><span>│       ├── stylelint-config/</span></span>
<span class="line"><span>│       └── commitlint-config/</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── scripts/clean.mjs</span></span>
<span class="line"><span>├── turbo.json</span></span>
<span class="line"><span>├── pnpm-workspace.yaml</span></span>
<span class="line"><span>├── eslint.config.mjs</span></span>
<span class="line"><span>├── unocss.config.ts</span></span>
<span class="line"><span>└── lefthook.yml</span></span></code></pre></div><h2 id="package-splitting-rationale" tabindex="-1">Package Splitting Rationale <a class="header-anchor" href="#package-splitting-rationale" aria-label="Permalink to &quot;Package Splitting Rationale&quot;">​</a></h2><h3 id="packages-core-shared" tabindex="-1"><code>packages/@core/shared</code> <a class="header-anchor" href="#packages-core-shared" aria-label="Permalink to &quot;\`packages/@core/shared\`&quot;">​</a></h3><p>The lowest-level package — <strong>depends on no other workspace packages</strong>:</p><ul><li>Constants (TOKEN_KEY, LOCALE_KEY, etc.)</li><li>Core TypeScript interfaces (IResponse, RoleType, ViteEnv)</li></ul><h3 id="packages-utils" tabindex="-1"><code>packages/utils</code> <a class="header-anchor" href="#packages-utils" aria-label="Permalink to &quot;\`packages/utils\`&quot;">​</a></h3><p>Pure utility functions, depends only on <code>@core/shared</code>:</p><ul><li>Auth: <code>getToken / setToken / clearToken</code></li><li>Date: <code>formatDate / formatDateTime</code></li><li>Helpers: <code>deepMerge / throttle / debounce</code></li></ul><h3 id="packages-stores" tabindex="-1"><code>packages/stores</code> <a class="header-anchor" href="#packages-stores" aria-label="Permalink to &quot;\`packages/stores\`&quot;">​</a></h3><p>Pinia stores, depends on <code>@core/shared</code> and <code>utils</code>:</p><ul><li><code>useUserStore</code> — token, userName, avatar, role (persisted)</li><li><code>useAppStore</code> — theme, locale, collapsed (persisted)</li></ul><h3 id="packages-effects-request" tabindex="-1"><code>packages/effects/request</code> <a class="header-anchor" href="#packages-effects-request" aria-label="Permalink to &quot;\`packages/effects/request\`&quot;">​</a></h3><p>HTTP client, depends on <code>@core/shared</code> and <code>utils</code>:</p><ul><li><code>createHttpClient</code> — axios instance with interceptors</li><li><code>createRequest</code> — type-safe <code>{get, post, put, del}</code> wrapper</li></ul><h3 id="packages-effects-access" tabindex="-1"><code>packages/effects/access</code> <a class="header-anchor" href="#packages-effects-access" aria-label="Permalink to &quot;\`packages/effects/access\`&quot;">​</a></h3><p>Route guard, depends on <code>stores</code>:</p><ul><li><code>setupAccessGuard</code> — global router guard</li><li><code>accessDirective</code> — <code>v-access</code> permission directive</li></ul><h3 id="internal-vite-config" tabindex="-1"><code>internal/vite-config</code> <a class="header-anchor" href="#internal-vite-config" aria-label="Permalink to &quot;\`internal/vite-config\`&quot;">​</a></h3><p>Engineering-only package, provides <code>defineConfig</code> factory. <strong>Must be pre-compiled</strong> because <code>vite.config.ts</code> runs in Node.js context (not Vite&#39;s bundler) and can&#39;t directly execute TypeScript.</p><h2 id="key-technical-decisions" tabindex="-1">Key Technical Decisions <a class="header-anchor" href="#key-technical-decisions" aria-label="Permalink to &quot;Key Technical Decisions&quot;">​</a></h2><h3 id="why-do-packages-export-typescript-directly" tabindex="-1">Why do <code>packages/*</code> export TypeScript directly? <a class="header-anchor" href="#why-do-packages-export-typescript-directly" aria-label="Permalink to &quot;Why do \`packages/*\` export TypeScript directly?&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./src/index.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Because they&#39;re only referenced from app source code processed by Vite, which can compile TypeScript natively. Direct TypeScript exports mean HMR works instantly when packages are modified.</p><h3 id="why-does-internal-vite-config-need-pre-compilation" tabindex="-1">Why does <code>internal/vite-config</code> need pre-compilation? <a class="header-anchor" href="#why-does-internal-vite-config-need-pre-compilation" aria-label="Permalink to &quot;Why does \`internal/vite-config\` need pre-compilation?&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;import&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./dist/index.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><code>vite.config.ts</code> runs in Node.js before Vite starts. Node.js ESM cannot execute <code>.ts</code> files, so the package must be compiled to <code>.js</code> first.</p><h3 id="why-share-unocss-config-ts-at-root" tabindex="-1">Why share <code>unocss.config.ts</code> at root? <a class="header-anchor" href="#why-share-unocss-config-ts-at-root" aria-label="Permalink to &quot;Why share \`unocss.config.ts\` at root?&quot;">​</a></h3><p>All apps use the same atomic CSS presets, shortcuts, and safelist. Centralizing this prevents style inconsistencies across UI ecosystems.</p>`,33)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
